begin;do $$declare quiz uuid;question uuid;begin select id into quiz from public.quizzes where slug='general-waste-foundation' and version=1; if not exists(select 1 from public.quiz_questions where quiz_id=quiz and position=1) and not exists(select 1 from public.quiz_attempts where quiz_id=quiz) then insert into public.quiz_questions(quiz_id,position,prompt,choices) values(quiz,1,'ก่อนส่งขวดเครื่องดื่มไปรีไซเคิลควรทำอย่างไร?','["เทของเหลวและตรวจเงื่อนไขจุดรับ", "ใส่เศษอาหารลงขวด", "ทิ้งรวมถ่านไฟฉาย"]'::jsonb) returning id into question;insert into private.quiz_answer_keys(question_id,answer,explanation) values(question,0,'เทของเหลวเมื่อปลอดภัยและเตรียมตามข้อกำหนดของจุดรับ');end if;end;$$;commit;